#include "baremetal_libc.h"

#define safe_printf printf

#define SHADOW_OFFSET 0x4000
#define MAPPING_MIN 0x20000000
#define MAPPING_MAX 0x20020000
#define MAPPING_SCALE 3
#define SHADOW_GRANULARITY (1 << MAPPING_SCALE)

#ifndef SPLIT_SHADOW
#define SPLIT_SHADOW
#endif
