#ifdef REGISTER_GLOBALS
extern "C" __attribute__((constructor(1)))
void __asan_register_globals() {
  for (__asan_global *g = &__asan_global_metadata$$Base[0];
       g < &__asan_global_metadata$$Limit; ++g) {
    size_t redzone_size = getRedzoneSizeForGlobal(g->size);
    if (g->beg < MAPPING_MIN || (g->beg + g->size + redzone_size) >= MAPPING_MAX)
      continue;
    unpoison_mem(g->beg, g->size, redzone_size, 0xf9);
  }
}

extern "C" void __asan_register_elf_globals(uintptr_t flag, uintptr_t start, uintptr_t stop) {
  if (start == 0 || stop == 0)
    return;
  __asan_global *g_start = (__asan_global *)start;
  __asan_global *g_stop = (__asan_global *)stop;
  for (__asan_global *g = g_start; g < g_stop; ++g) {
    size_t redzone_size = getRedzoneSizeForGlobal(g->size);
    if (g->beg < MAPPING_MIN || (g->beg + g->size + redzone_size) >= MAPPING_MAX)
      continue;
    unpoison_mem(g->beg, g->size, redzone_size, 0xf9);
  }
}

extern "C" void __asan_register_image_globals(uintptr_t flag) {
  __asan_register_globals();
}

extern "C" void __asan_unregister_image_globals(uintptr_t flag) {
}

extern "C" void __asan_unregister_globals(void *, unsigned) {
}
extern "C" void __asan_unregister_elf_globals(uintptr_t flag, uintptr_t start, uintptr_t stop) {
}
#endif

