// {{{ Alloca

static const size_t kAllocaRedzoneSize = 32;
static const size_t kAllocaRedzoneMask = 31UL;
const int kAsanAllocaLeftMagic = 0xca;
const int kAsanAllocaRightMagic = 0xcb;

extern "C" void __asan_alloca_poison(uintptr_t addr, uintptr_t size) {
  uintptr_t left_redzone = addr - kAllocaRedzoneSize;
  uintptr_t PartialRzAddr = addr + size;
  uintptr_t RightRzAddr = (PartialRzAddr + kAllocaRedzoneMask) & ~kAllocaRedzoneMask;
  uintptr_t PartialRzAligned = PartialRzAddr & ~(SHADOW_GRANULARITY - 1);
  size_t right_redzone_len = ((size + 31) & ~0x1f) - size + 32;
  poison_mem(left_redzone, kAllocaRedzoneSize, kAsanAllocaLeftMagic);
  poison_mem_right_redzone(addr, size, right_redzone_len, kAsanAllocaRightMagic);
}

extern "C" void __asan_allocas_unpoison(uintptr_t top, uintptr_t bottom) {
  // "top" and "bottom" are the names compiler-rt uses for these pointers, but
  // top is actually the lower-addressed one for descending stacks.
  unpoison_mem(top, bottom - top, 0, 0);
}

// {{{ Shadow of Shadow Protection

extern "C" void __asan_protect_shadow_of_shadow(uintptr_t shadow_start,
                                                uintptr_t shadow_end) {
  uintptr_t sos_start = (uintptr_t)get_shadow_addr(shadow_start);
  uintptr_t sos_end = (uintptr_t)get_shadow_addr(shadow_end);
  if (sos_end > sos_start) {
    // Pre-poison the shadow-of-shadow region with 0xff so inline checks (*S(A) != 0) naturally trap.
    poison_mem(sos_start, sos_end - sos_start, 0xff);
  }
}

